module cme_feed_parser (
    clk,
    data,
    rst,
    valid,
    data_out,
    slave_ready
);

    input clk;
    input [511:0] data;
    input rst;
    input valid;
    output [511:0] data_out;
    output slave_ready;

    wire vdd;
    wire [511:0] signal_const;
    assign vdd = 1'b1;
    assign signal_const = 512';
    assign data_out = signal_const;
    assign slave_ready = vdd;

endmodule
